reference_solution:
n = int(input())
for i in range(1, n + 1):
    print(f"TICK-{i:03d}")

n = int(input())
divs = []
for i in range(1, n + 1):
    if n % i == 0:
        divs.append(str(i))
print("Divisors: " + " ".join(divs))

n = int(input())
for i in range(1, n + 1):
    print("#" * i)

a, b = map(int, input().split())
primes = []
for num in range(a, b + 1):
    if num < 2:
        continue
    is_prime = True
    i = 2
    while i * i <= num:
        if num % i == 0:
            is_prime = False
            break
        i += 1
    if is_prime:
        primes.append(str(num))
if primes:
    print("Primes: " + " ".join(primes))
else:
    print("No primes found")

n = int(input())
mid = n // 2
for i in range(n):
    lead = abs(mid - i)
    k = mid - lead
    if k == 0:
        print(" " * lead + "#")
    else:
        print(" " * lead + "#" + " " * (2 * k - 1) + "#")

n = int(input())
parts = []
p = 2
while p * p <= n:
    if n % p == 0:
        k = 0
        while n % p == 0:
            n //= p
            k += 1
        parts.append(f"{p}^{k}" if k > 1 else str(p))
    p += 1
if n > 1:
    parts.append(str(n))
if not parts:
    parts.append("1")
print("Factorization: " + " x ".join(parts))

a, b = map(int, input().split())
found = []
for num in range(a, b + 1):
    d = len(str(num))
    total = 0
    t = num
    while t > 0:
        total += (t % 10) ** d
        t //= 10
    if total == num:
        found.append(str(num))
if found:
    print("Armstrong numbers: " + " ".join(found))
else:
    print("No Armstrong numbers found")
